import re, html
for slug in ['clover','mcherry']:
    txt=open(f'/app/fpbase_{slug}.html').read()
    print('===',slug,'=== sequence-related snippets ===')
    # Find strings around known sequence pattern markers
    for pat in [r'(?s)MVSKGE[^<]{0,400}', r'(?s)VSKGE[^<]{0,400}', r'(?s)MDELYK[^<]{0,100}', r'(?s)sequence.{0,500}', r'(?s)protein sequence.{0,500}']:
        ms=re.findall(pat, txt, re.I)
        if ms:
            print('PAT',pat)
            for m in ms[:2]:
                print(re.sub('<[^>]+>',' ',html.unescape(m))[:600])
